{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 자전거 안전교육 인증으로 따릉이(공공자전거) 이용요금 할인 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시 자전거 안전교육 인증을 받은 사람은 공공자전거 이용요금 감면 대상자 기준에 포함된다. 조례 제12조의3제1항은 시장이 공공자전거 이용 시민 등을 대상으로 이용요금의 일부 또는 전부를 감면할 수 있다고 정하고, 같은 조 제2항제6호는 제13조제6항에 따른 자전거 교통안전교육 인증을 받은 사람을 감면 대상자로 열거한다. 다만 감면의 구체적 적용 여부·조건·절차는 시장이 따로 정하도록 되어 있어, 인증만으로 할인이 실제로 적용되는지는 이 조문만으로 확정되지 않는다.",
          "b_ids": "자전거:제12조의3제1항, 자전거:제12조의3제2항제6호, 자전거:제13조제6항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
